// Generated by scripts/setup-ci.mjs; extended with the React plugin.
import { execSync } from 'node:child_process';
import { cpSync, createReadStream, existsSync, statSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join, normalize, sep } from 'node:path';
import react from '@vitejs/plugin-react';
import type { Plugin } from 'vite';
import { defineConfig } from 'vitest/config';

/**
 * pdf.js needs its CMaps (for fonts using predefined Adobe CMaps, e.g. Japanese 90ms-RKSJ-H) and
 * standard font data at run time. Serve them from node_modules in dev and copy them next to the
 * build, under `pdfjs/` (see src/pdf/render.ts).
 */
function pdfjsAssets(): Plugin {
  const root = dirname(createRequire(import.meta.url).resolve('pdfjs-dist/package.json'));
  const dirs = ['cmaps', 'standard_fonts'];
  return {
    name: 'pdfjs-assets',
    configureServer(server) {
      server.middlewares.use('/pdfjs', (req, res, next) => {
        const rel = decodeURIComponent((req.url ?? '').split('?')[0] ?? '');
        const file = normalize(join(root, rel));
        const dir = rel.replace(/^\//, '').split('/')[0] ?? '';
        if (!dirs.includes(dir) || !file.startsWith(root + sep)) return next();
        if (!existsSync(file) || !statSync(file).isFile()) return next();
        res.setHeader('Content-Type', 'application/octet-stream');
        createReadStream(file).pipe(res);
      });
    },
    writeBundle(options) {
      const out = options.dir ?? 'dist';
      for (const d of dirs) cpSync(join(root, d), join(out, 'pdfjs', d), { recursive: true });
    },
  };
}

/** Commit the app was built from, stamped into bug reports ("+dirty" with uncommitted changes). */
function commitId(): string {
  try {
    const sha = execSync('git rev-parse --short HEAD', { encoding: 'utf8' }).trim();
    const dirty = execSync('git status --porcelain', { encoding: 'utf8' }).trim() !== '';
    return dirty ? `${sha}+dirty` : sha;
  } catch {
    return 'unknown';
  }
}

export default defineConfig({
  plugins: [react(), pdfjsAssets()],
  define: { __APP_COMMIT__: JSON.stringify(commitId()) },
  base: './',
  test: {
    globals: true,
    environment: 'node',
    passWithNoTests: true,
  },
});
